package com.aistock.gateway.adminmarket;
import com.aistock.common.*;import com.aistock.common.adminmarket.AdminMarketQuery;import com.aistock.common.marketrefs.MarketReferenceInput;import com.aistock.gateway.*;import com.aistock.gateway.security.AdminReadAccess;import com.fasterxml.jackson.databind.*;import jakarta.servlet.http.*;import java.io.IOException;import org.springframework.http.*;import org.springframework.util.MultiValueMap;import org.springframework.web.bind.annotation.*;
@RestController public class MarketReferenceProxyController {
 private final MarketReferencePublicClient client;private final AdminReadAccess access;private final ObjectMapper mapper;
 public MarketReferenceProxyController(MarketReferencePublicClient client,AdminReadAccess access,ObjectMapper mapper){this.client=client;this.access=access;this.mapper=mapper.copy().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS).enable(com.fasterxml.jackson.core.JsonParser.Feature.STRICT_DUPLICATE_DETECTION);}
 @RequestMapping("/api/v1/admin/market-data/{instrumentId}/versions/{versionId}/references") public ResponseEntity<byte[]> inspect(@PathVariable String instrumentId,@PathVariable String versionId,@RequestParam MultiValueMap<String,String> query,HttpServletRequest r,HttpServletResponse response)throws IOException{
  response.setHeader("Cache-Control","no-store");if(!"GET".equals(r.getMethod())||!MarketReferenceInput.publicPath(r.getRequestURI()))throw new BusinessException("RESOURCE_NOT_FOUND","接口不存在",HttpStatus.NOT_FOUND);access.requireAdmin(r);if(!query.isEmpty()||r.getInputStream().read()!=-1)throw AdminMarketQuery.invalid();
  try{ResponseEntity<byte[]> reply;try{reply=client.inspect(instrumentId,versionId,ProxyHeaderPolicy.request(r));}catch(feign.FeignException e){reply=ResponseEntity.status(e.status()>0?e.status():503).body(e.content());}if(reply==null||reply.getBody()==null||reply.getBody().length>65536)throw unavailable();var n=mapper.reader().with(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).readTree(reply.getBody());if(n==null||!n.isObject())throw unavailable();int status=reply.getStatusCode().value();String code=n.path("code").asText();if(status!=200||!"OK".equals(code))throw upstream(status,code);if(!n.path("data").isObject())throw unavailable();var report=MarketReferenceInput.decodeReport(mapper.writeValueAsBytes(n.get("data")),instrumentId,versionId);return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).cacheControl(CacheControl.noStore()).body(mapper.writeValueAsBytes(ApiResponse.success(report,TraceIds.normalize(r.getHeader("X-Trace-Id")))));
  }catch(BusinessException e){throw e;}catch(IOException|RuntimeException e){throw unavailable();}
 }
 private BusinessException upstream(int status,String code){if(status==400&&"MARKET_ADMIN_QUERY_INVALID".equals(code))return AdminMarketQuery.invalid();if(status==401&&"AUTH_REQUIRED".equals(code))return new BusinessException(code,"请重新登录",HttpStatus.UNAUTHORIZED);if(status==403&&"ACCESS_DENIED".equals(code))return new BusinessException(code,"仅管理员可以检查引用",HttpStatus.FORBIDDEN);if(status==404&&"MARKET_ADMIN_RESOURCE_NOT_FOUND".equals(code))return new BusinessException(code,"未找到所属股票的行情版本",HttpStatus.NOT_FOUND);if(status==503&&"USER_SERVICE_UNAVAILABLE".equals(code))return new BusinessException(code,"账号服务暂不可用",HttpStatus.SERVICE_UNAVAILABLE);return unavailable();}
 private BusinessException unavailable(){return new BusinessException("MARKET_ADMIN_UNAVAILABLE","版本引用暂无法核对，请稍后刷新",HttpStatus.SERVICE_UNAVAILABLE);}
}
